    private Object value;

    public TokenBuilder(String type, Object value) {
        this.type = type;
        this.value = value;
    }

    // Add methods to construct tokens
    public TokenBuilder type(String type) {
        this.type = type;
        return this;
    }

    public TokenBuilder value(Object value) {
        this.value = value;
        return this;
    }

    public Token build() {
        return new Token(type, value);
    }
}

class TokenBuilderComment extends TokenBuilder {
    private String message;

    public TokenBuilderComment(String message) {
        super("comment", message);
    }

    @Override
    public Token build() {
        this.message = message;
        return this.build();
    }
}

class TokenBuilderList extends TokenBuilder {
    private Object[] elements;

    public TokenBuilderList(Object... elements) {
        this.elements = elements;
    }

    // Add methods to construct tokens in a list
    public TokenBuilderList addElement(Object element) {
        this.elements.push(element);
        return this.build();
    }
}

class TokenList {
    private List<Token> tokens;

    public TokenList() {
        this.tokens = new ArrayList<>();
    }

    public void addToken(Token token) {
        this.tokens.add(token);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Token token : tokens) {
            sb.append(token.getType()).append(" ").append(token.getValue().toString()).append("\n");
        }
        return sb.toString();
    }
}

public class Main {
    public static void main(String[] args) {
        TokenBuilder builder = new TokenBuilder("code", "sample code");

        TokenBuilderComment comment = builder.type("comment")
                .value("This is a sample code.");

        TokenList list = new TokenList();

        list.addToken(comment.build());
        list.addToken(new TokenBuilderList("list1").addElement(1).build());
        list.addToken(new TokenBuilderList("list2").addElement(2).build());

        System.out.println(list.toString());
    }
}
